 		/* Skip elements below offset */
 		if (i + len < offset << shift) {
 			i += len;
 			continue;
 		}

 		/* Skip pages below offset */
 		if (i < offset << shift) {
 			k = (offset << shift) - i;
 			i = offset << shift;
 		} else {
